lagrange-basis-polynomial.pseudocode:
def basis(xs, i, x):
    L = 1.0
    for j in range(len(xs)):
        if j != i:  # j = i 항은 제외한 곱
            L *= (x - xs[j]) / (xs[i] - xs[j])
    return L  # xs[i]에서 1, 다른 xs[j]에서 0

def interpolate(xs, ys, x):
    # P(x) = Σ yi · Li(x)
    return sum(ys[i] * basis(xs, i, x)
               for i in range(len(xs)))

laplace-mechanism.pseudocode:
def laplace_noise(b):
    # 역변환 샘플링: u ~ Uniform(-0.5, 0.5)
    u = uniform(-0.5, 0.5)
    return -b * sign(u) * log(1 - 2 * abs(u))

def laplace_mechanism(true_answer, sensitivity, epsilon):
    b = sensitivity / epsilon  # 잡음 규모 Δf/ε
    return true_answer + laplace_noise(b)

# 예: 개수 질의 Δf = 1, ε = 0.5 → b = 2
# noisy = laplace_mechanism(count, 1, 0.5)

law-of-demeter.pseudocode:
# 위반: 고객 내부 구조(지갑)를 따라 체이닝
def charge_bad(customer, amount):
    wallet = customer.get_wallet()
    if wallet.get_balance() >= amount:
        wallet.subtract(amount)

# 준수: 직접 아는 객체에게만 요청하고 위임
class Customer:
    def pay(self, amount):
        return self.wallet.withdraw(amount)  # 멤버에게만

def charge_good(customer, amount):
    return customer.pay(amount)  # 매개변수에게만

layer-of-protection-analysis.pseudocode:
def lopa(f_ie, ipl_pfds, tolerable):
    f = f_ie  # 초기 사건 빈도 (회/년)
    for pfd in ipl_pfds:
        f *= pfd  # 독립 방호계층마다 빈도 감소
    if f <= tolerable:
        return f, None  # 추가 방호 불필요
    need = tolerable / f  # 추가 SIF에 요구되는 PFD
    if need >= 0.1:
        return f, 0  # SIL 미만 방호로 충분
    for sil, low in [(1, 1e-2), (2, 1e-3), (3, 1e-4)]:
        if need >= low:
            return f, sil  # 요구 SIL 등급
    return f, 4  # SIL4 수준 → 공정 설계 재검토 권장
